<?php

namespace app\services;

use Yii;
use app\models\Order;
use app\models\OrderItem;
use yii\base\Component;
use yii\web\ServerErrorHttpException;

class OrderCreationService extends Component
{
    /**
     * Creates an order with items inside a single database transaction.
     *
     * @param int $customerId
     * @param array<array{product_id: int, quantity: int, price: float}> $itemsData
     * @return Order
     * @throws ServerErrorHttpException
     */
    public function createOrderWithItems(int $customerId, array $itemsData): Order
    {
        $db = Yii::$app->db;
        $transaction = $db->beginTransaction();

        try {
            $order = new Order();
            $order->customer_id = $customerId;
            $order->status = Order::STATUS_PENDING;
            $order->total_amount = 0.0;

            if (!$order->save()) {
                throw new \Exception('Failed to create order: ' . json_encode($order->errors));
            }

            $total = 0.0;
            foreach ($itemsData as $itemData) {
                $item = new OrderItem();
                $item->order_id = $order->id;
                $item->product_id = $itemData['product_id'];
                $item->quantity = $itemData['quantity'];
                $item->unit_price = $itemData['price'];

                if (!$item->save()) {
                    throw new \Exception('Failed to save order item: ' . json_encode($item->errors));
                }
                $total += $item->quantity * $item->unit_price;
            }

            $order->total_amount = $total;
            $order->update(false, ['total_amount']);

            $transaction->commit();
            return $order;
        } catch (\Throwable $e) {
            $transaction->rollBack();
            Yii::error('Order creation failed: ' . $e->getMessage(), __METHOD__);
            throw new ServerErrorHttpException('Could not process order. ' . $e->getMessage());
        }
    }
}
